	struct wacom_remote *remote = wacom->remote;
	ktime_t kt = ktime_get();
	struct wacom_remote_work_data remote_work_data;
	unsigned long flags;
	unsigned int count;
	u32 work_serial;
	int i;

	spin_lock_irqsave(&remote->remote_lock, flags);

